const BUNDLE_ID = "crown-ten-thousandfold-gaze-v11";
const ITEM_NAME = "Корона Десятитысячного Взора v1.1";
const JOURNAL_NAME = "Памятка: Корона Десятитысячного Взора v1.1";
const FOLDER_NAME = "Артефакты бехолдеров";
const IMG_PATH = "assets/crown-ten-thousandfold-gaze.png";
let IMG = "icons/commodities/treasure/crown-gold-purple.webp";

const EYES = {
  charm: { label: "Глаз Очарования", limit: 1, period: "day" },
  paralysis: { label: "Глаз Паралича", limit: 1, period: "day" },
  fear: { label: "Глаз Страха", limit: 1, period: "day" },
  slow: { label: "Глаз Замедления", limit: 3, period: "day" },
  exhaustion: { label: "Глаз Истощения", limit: 1, period: "day" },
  telekinesis: { label: "Телекинетический Глаз", limit: null, period: "none" },
  sleep: { label: "Глаз Сна", limit: 1, period: "day" },
  decay: { label: "Глаз Разложения", limit: 3, period: "day" },
  petrification: { label: "Глаз Окаменения", limit: 1, period: "day" },
  disintegration: { label: "Глаз Дезинтеграции", limit: 1, period: "week" }
};

const DEFAULT_ACTIVE_EYES = ["charm", "paralysis", "fear"];

function asset(bundle, localPath) {
  return bundle?.assets?.[localPath] ?? `modules/ai-patcher/inbox/${BUNDLE_ID}/${localPath}`;
}

function clone(data) {
  return foundry.utils.deepClone(data);
}

function activityValues(activities) {
  if (!activities) return [];
  if (activities.contents) return activities.contents;
  if (activities.values) return Array.from(activities.values());
  return Object.values(activities);
}

async function getOrCreateFolder(name, type) {
  let folder = game.folders.find((entry) => entry.type === type && entry.name === name);
  if (folder) return folder;
  return Folder.create({ name, type });
}

function baseDamage(number, denomination, types, bonus = "") {
  return {
    number,
    denomination,
    bonus,
    types,
    custom: { enabled: false, formula: "" },
    scaling: { mode: "", number: null, formula: "" }
  };
}

function itemMacroFlags(command) {
  return {
    itemacro: {
      macro: {
        name: `${ITEM_NAME} ItemMacro`,
        type: "script",
        img: IMG,
        scope: "global",
        command,
        author: game.user.id,
        ownership: { default: 0, [game.user.id]: 3 }
      }
    },
    "midi-qol": {
      onUseMacroName: `${ITEM_NAME} ItemMacro,[preItemRoll]ItemMacro,[preTargeting]ItemMacro,[postActiveEffects]ItemMacro`
    }
  };
}

function htmlDescription() {
  return `
<div class="ai-patcher-item-description">
  <p><em>Это не просто артефакт бехолдера. Это фрагмент сознания самого бога-глаза. После смерти Ксал'Тариса часть его глаз сплавилась в живую корону из нервов, хитина и левитирующих глазных яблок. Иногда она моргает сама по себе.</em></p>

  <h3>Legendary Wondrous Item</h3>
  <p><strong>Чудесный предмет, легендарный, требует настройки.</strong></p>

  <h3>Базовые свойства</h3>
  <ul>
    <li>Тёмное зрение 120 фт.</li>
    <li>Преимущество на проверки Восприятия.</li>
    <li>Носителя нельзя застать врасплох.</li>
  </ul>

  <h3>Система глаз</h3>
  <p>У короны 10 глаз, но одновременно активны только 3. После продолжительного отдыха владелец выбирает активные глаза через активность <strong>Настроить активные глаза</strong>.</p>

  <h3>Паранойя Всевидящего</h3>
  <p>Каждый раз, когда используется глаз, бросается d20. При 1 корона пытается подчинить носителя: спасбросок Мудрости СЛ 19. При провале носитель получает состояние <strong>Паранойя Всевидящего</strong>: он уверен, что за ним наблюдают, а ведущий один раз может навязать ему действие.</p>

  <h3>Скрытый эффект</h3>
  <p>Если владелец использует 3 разных глаза в одном бою, вокруг него появляются фантомные глаза. Существа в 10 фт получают помеху на спасброски Мудрости против страха.</p>

  <h3>Проклятие</h3>
  <p>Корону невозможно снять добровольно после настройки. Каждые 30 дней носитель совершает спасбросок Мудрости СЛ 17. При провале он видит стены из глаз, наблюдателей и истинную геометрию. После 3 провалов один глаз персонажа физически мутирует.</p>
</div>`;
}

function chatDescription() {
  return "Легендарная живая корона бога-бехолдера: 10 глаз, 3 активных, лучи, паранойя, фантомные глаза и проклятие неснимаемой настройки.";
}

const CROWN_MACRO = [
`const EYES = ${JSON.stringify(EYES)};`,
`const DEFAULT_ACTIVE_EYES = ${JSON.stringify(DEFAULT_ACTIVE_EYES)};`,
String.raw`
const ITEM_FLAG_SCOPE = "world";
const ACTIVE_FLAG = "tenThousandfoldGazeActiveEyes";
const USES_FLAG = "tenThousandfoldGazeUses";
const COMBAT_FLAG = "tenThousandfoldGazeCombatEyes";
const PETRIFY_FLAG = "tenThousandfoldGazePetrifyFailures";
const CURSE_FLAG = "tenThousandfoldGazeCurseFailures";

function activityName() {
  return args?.[0]?.workflow?.activity?.name ?? args?.[0]?.activity?.name ?? "";
}
function currentEyeKey() {
  const name = activityName();
  return Object.entries(EYES).find(([, eye]) => eye.label === name)?.[0] ?? null;
}
function todayKey() {
  return new Date().toISOString().slice(0, 10);
}
function weekKey() {
  const now = new Date();
  const first = new Date(Date.UTC(now.getUTCFullYear(), 0, 1));
  const day = Math.floor((Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()) - first) / 86400000) + 1;
  return String(now.getUTCFullYear()) + "-W" + Math.ceil(day / 7);
}
function usageBucket(eye) {
  if (eye.period === "week") return weekKey();
  if (eye.period === "day") return todayKey();
  return "none";
}
function getActiveEyes(sourceItem) {
  const active = sourceItem?.getFlag(ITEM_FLAG_SCOPE, ACTIVE_FLAG);
  return Array.isArray(active) && active.length === 3 ? active : DEFAULT_ACTIVE_EYES;
}
function usageKey(eyeKey) {
  const eye = EYES[eyeKey];
  return eyeKey + ":" + usageBucket(eye);
}
async function checkLimit(sourceItem, eyeKey) {
  const eye = EYES[eyeKey];
  if (!eye?.limit) return true;
  const uses = sourceItem.getFlag(ITEM_FLAG_SCOPE, USES_FLAG) ?? {};
  const used = Number(uses[usageKey(eyeKey)] ?? 0);
  if (used < eye.limit) return true;
  ui.notifications?.warn(eye.label + ": лимит использований исчерпан.");
  return false;
}
async function spendUse(sourceItem, eyeKey) {
  const eye = EYES[eyeKey];
  if (!eye?.limit) return;
  const uses = foundry.utils.deepClone(sourceItem.getFlag(ITEM_FLAG_SCOPE, USES_FLAG) ?? {});
  const key = usageKey(eyeKey);
  uses[key] = Number(uses[key] ?? 0) + 1;
  await sourceItem.setFlag(ITEM_FLAG_SCOPE, USES_FLAG, uses);
}
function selfTokenFor(selfActor) {
  return token ?? canvas.tokens.controlled[0] ?? canvas.tokens.placeables.find(t => t.actor?.id === selfActor?.id);
}
function tokenDistance(a, b) {
  if (!a || !b) return Infinity;
  if (canvas.grid?.measurePath) return Number(canvas.grid.measurePath([a.center, b.center])?.distance ?? Infinity);
  const dx = a.center.x - b.center.x;
  const dy = a.center.y - b.center.y;
  return Math.hypot(dx, dy) / canvas.grid.size * (canvas.scene.grid.distance || 5);
}
async function applyEffect(targetActor, data) {
  const old = targetActor.effects.filter(e => e.getFlag("ai-patcher", data.flag));
  if (old.length) await targetActor.deleteEmbeddedDocuments("ActiveEffect", old.map(e => e.id));
  await targetActor.createEmbeddedDocuments("ActiveEffect", [{
    name: data.name,
    icon: data.icon ?? item.img,
    origin: item.uuid,
    duration: data.duration ?? { rounds: 10 },
    statuses: data.statuses ?? [],
    changes: data.changes ?? [],
    description: data.description ?? "",
    flags: {
      "ai-patcher": { [data.flag]: true, bundleId: "crown-ten-thousandfold-gaze-v11" },
      dae: data.dae ?? {}
    }
  }]);
}
async function rollWisSave(selfActor, dc, label) {
  let roll = null;
  if (selfActor?.rollAbilitySave) {
    roll = await selfActor.rollAbilitySave("wis", { flavor: label, targetValue: dc });
  } else {
    const mod = Number(selfActor?.system?.abilities?.wis?.save ?? selfActor?.system?.abilities?.wis?.mod ?? 0);
    roll = await new Roll("1d20 + " + mod).evaluate();
    await roll.toMessage({ speaker: ChatMessage.getSpeaker({ actor: selfActor }), flavor: label });
  }
  return Number(roll?.total ?? 0);
}
async function runParanoiaCheck(selfActor) {
  const d20 = await new Roll("1d20").evaluate();
  await d20.toMessage({ speaker: ChatMessage.getSpeaker({ actor: selfActor }), flavor: "Паранойя Всевидящего: проверка короны" });
  if (d20.total !== 1) return false;
  const total = await rollWisSave(selfActor, 19, "Корона пытается подчинить носителя: спасбросок Мудрости СЛ 19");
  if (total >= 19) {
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: selfActor }), content: "<p><strong>Паранойя Всевидящего.</strong> Носитель подавляет волю короны.</p>" });
    return false;
  }
  await applyEffect(selfActor, {
    name: "Паранойя Всевидящего",
    icon: item.img,
    flag: "tenThousandfoldParanoia",
    duration: { rounds: 10 },
    description: "Носитель уверен, что за ним наблюдают. Ведущий один раз может навязать ему действие."
  });
  await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: selfActor }), content: "<p><strong>Паранойя Всевидящего.</strong> Корона нашёптывает носителю чужое действие. Ведущий получает один приказ над персонажем.</p>" });
  return true;
}
async function noteCombatEye(sourceItem, selfActor, eyeKey) {
  const combatId = game.combat?.id ?? "no-combat";
  const all = foundry.utils.deepClone(sourceItem.getFlag(ITEM_FLAG_SCOPE, COMBAT_FLAG) ?? {});
  const used = Array.isArray(all[combatId]) ? all[combatId] : [];
  if (!used.includes(eyeKey)) used.push(eyeKey);
  all[combatId] = used;
  await sourceItem.setFlag(ITEM_FLAG_SCOPE, COMBAT_FLAG, all);
  if (combatId === "no-combat" || used.length < 3) return;
  const self = selfTokenFor(selfActor);
  await applyEffect(selfActor, {
    name: "Фантомные глаза",
    icon: item.img,
    flag: "tenThousandfoldPhantomEyesSelf",
    duration: { rounds: 10 },
    description: "После использования трёх разных глаз в одном бою вокруг носителя появляются фантомные глаза."
  });
  const targets = canvas.tokens.placeables.filter(t => t.actor && t.id !== self?.id && tokenDistance(self, t) <= 10);
  for (const target of targets) {
    await applyEffect(target.actor, {
      name: "Под взглядом фантомных глаз",
      icon: item.img,
      flag: "tenThousandfoldPhantomEyesTarget",
      duration: { rounds: 10 },
      changes: [
        { key: "flags.midi-qol.disadvantage.ability.save.wis", mode: CONST.ACTIVE_EFFECT_MODES.CUSTOM, value: "1", priority: 20 }
      ],
      description: "Существо в 10 фт от носителя короны совершает спасброски Мудрости против страха с помехой."
    });
  }
}
async function configureEyes(sourceItem) {
  const active = new Set(getActiveEyes(sourceItem));
  const rows = Object.entries(EYES).map(([key, eye]) => {
    const checked = active.has(key) ? "checked" : "";
    const limit = eye.limit ? (eye.limit + "/" + (eye.period === "week" ? "неделю" : "день")) : "без ограничений";
    return '<label style="display:flex; gap:8px; align-items:flex-start; margin:4px 0;">' +
      '<input type="checkbox" name="eye" value="' + key + '" ' + checked + '>' +
      '<span><strong>' + eye.label + '</strong><br><small>' + limit + '</small></span>' +
      '</label>';
  }).join("");
  await new Promise((resolve) => {
    new Dialog({
      title: "Настроить активные глаза",
      content: '<form><p>Выберите ровно <strong>3</strong> активных глаза после продолжительного отдыха.</p>' + rows + '</form>',
      buttons: {
        save: {
          icon: '<i class="fas fa-eye"></i>',
          label: "Сохранить",
          callback: async (html) => {
            const selected = Array.from(html[0].querySelectorAll('input[name="eye"]:checked')).map(input => input.value);
            if (selected.length !== 3) {
              ui.notifications?.warn("Нужно выбрать ровно 3 активных глаза.");
              resolve(false);
              return;
            }
            await sourceItem.setFlag(ITEM_FLAG_SCOPE, ACTIVE_FLAG, selected);
            await sourceItem.setFlag(ITEM_FLAG_SCOPE, USES_FLAG, {});
            ui.notifications?.info("Активные глаза: " + selected.map(k => EYES[k].label).join(", "));
            resolve(true);
          }
        },
        cancel: { label: "Отмена", callback: () => resolve(false) }
      },
      default: "save"
    }).render(true);
  });
}

const data = args?.[0] ?? {};
const pass = data.macroPass;
const sourceItem = item ?? data.workflow?.item;
const selfActor = actor ?? data.workflow?.actor;
const eyeKey = currentEyeKey();
if (!sourceItem) return;

if (activityName() === "Настроить активные глаза" && pass === "postActiveEffects") {
  await configureEyes(sourceItem);
  return;
}

if (activityName() === "Проверка проклятия 30 дней" && pass === "postActiveEffects") {
  if (!selfActor) return;
  const total = await rollWisSave(selfActor, 17, "Проклятие короны: спасбросок Мудрости СЛ 17");
  if (total >= 17) return ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: selfActor }), content: "<p><strong>Проклятие короны.</strong> Носитель выдерживает месяц наблюдения.</p>" });
  const failures = Number(selfActor.getFlag(ITEM_FLAG_SCOPE, CURSE_FLAG) ?? 0) + 1;
  await selfActor.setFlag(ITEM_FLAG_SCOPE, CURSE_FLAG, failures);
  if (failures >= 3) {
    await applyEffect(selfActor, { name: "Мутировавший глаз", icon: sourceItem.img, flag: "tenThousandfoldMutatedEye", duration: { seconds: 31536000 }, description: "Один глаз персонажа физически мутировал под влиянием истинной геометрии. Механических штрафов нет, но NPC реагируют иначе." });
  }
  return ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: selfActor }), content: "<p><strong>Проклятие короны.</strong> Провалов накоплено: <strong>" + failures + "/3</strong>. Носитель видит стены из глаз и истинную геометрию.</p>" });
}

if (!eyeKey) return;

if (pass === "preItemRoll" || pass === "preTargeting") {
  const active = getActiveEyes(sourceItem);
  if (!active.includes(eyeKey)) {
    ui.notifications?.warn(EYES[eyeKey].label + " сейчас не активен. После длинного отдыха используйте «Настроить активные глаза».");
    return false;
  }
  if (!(await checkLimit(sourceItem, eyeKey))) return false;
}

if (pass !== "postActiveEffects") return;
await spendUse(sourceItem, eyeKey);
await noteCombatEye(sourceItem, selfActor, eyeKey);
await runParanoiaCheck(selfActor);

const workflow = data.workflow ?? globalThis.workflow;
const failed = Array.from(workflow?.failedSaves ?? []);
const hit = Array.from(workflow?.hitTargets ?? []);
const targets = failed.length ? failed : hit;

if (eyeKey === "charm") {
  for (const target of failed) await applyEffect(target.actor, { name: "Очарован Десятитысячным Взором", flag: "tenThousandCharm", statuses: ["charmed"], duration: { rounds: 10 }, description: "Очарован короной на 1 минуту." });
}
if (eyeKey === "paralysis") {
  for (const target of failed) await applyEffect(target.actor, { name: "Паралич Десятитысячного Взора", flag: "tenThousandParalysis", statuses: ["paralyzed"], duration: { rounds: 1, turns: 1 }, dae: { specialDuration: ["turnEndSource"] }, description: "Парализован до конца следующего хода владельца короны." });
}
if (eyeKey === "fear") {
  for (const target of failed) await applyEffect(target.actor, { name: "Страх Десятитысячного Взора", flag: "tenThousandFear", statuses: ["frightened"], duration: { rounds: 10 }, description: "Испуган на 1 минуту." });
}
if (eyeKey === "slow") {
  for (const target of failed) await applyEffect(target.actor, {
    name: "Замедление Десятитысячного Взора",
    flag: "tenThousandSlow",
    duration: { rounds: 1, turns: 1 },
    changes: [
      { key: "system.attributes.ac.bonus", mode: CONST.ACTIVE_EFFECT_MODES.ADD, value: "-2", priority: 20 },
      { key: "flags.midi-qol.fail.reaction.all", mode: CONST.ACTIVE_EFFECT_MODES.CUSTOM, value: "1", priority: 20 }
    ],
    description: "Замедлен на 1 раунд без концентрации: -2 КД, без реакций; скорость и количество действий отследите по правилам Slow."
  });
}
if (eyeKey === "exhaustion") {
  for (const target of targets) {
    const current = Number(target.actor?.system?.attributes?.exhaustion ?? 0);
    await target.actor.update({ "system.attributes.exhaustion": current + 1 });
  }
}
if (eyeKey === "sleep") {
  for (const target of failed) await applyEffect(target.actor, { name: "Сон Десятитысячного Взора", flag: "tenThousandSleep", statuses: ["unconscious"], duration: { rounds: 10 }, description: "Цель засыпает как от Sleep, но независимо от текущих хитов. Эффект заканчивается при уроне или если другое существо разбудит цель действием." });
}
if (eyeKey === "petrification") {
  for (const target of failed) {
    const current = Number(target.actor.getFlag(ITEM_FLAG_SCOPE, PETRIFY_FLAG) ?? 0) + 1;
    await target.actor.setFlag(ITEM_FLAG_SCOPE, PETRIFY_FLAG, current);
    if (current >= 2) {
      await applyEffect(target.actor, { name: "Окаменение Десятитысячного Взора", flag: "tenThousandPetrified", statuses: ["petrified"], duration: { rounds: 10 }, description: "Второй провал против Глаза Окаменения: цель окаменела." });
      await target.actor.setFlag(ITEM_FLAG_SCOPE, PETRIFY_FLAG, 0);
    } else {
      await applyEffect(target.actor, { name: "Начало окаменения", flag: "tenThousandPetrifying", duration: { rounds: 10 }, description: "Первый провал против Глаза Окаменения. Второй провал подряд окаменит цель." });
    }
  }
}
if (eyeKey === "disintegration") {
  for (const target of hit) {
    const hp = Number(target.actor?.system?.attributes?.hp?.value ?? 1);
    if (hp <= 0) await applyEffect(target.actor, { name: "Дезинтегрирован", flag: "tenThousandDisintegrated", duration: { seconds: 86400 }, description: "Цель была сведена к серой пыли Глазом Дезинтеграции." });
  }
}
if (["charm", "paralysis", "fear", "slow", "exhaustion", "sleep", "petrification", "disintegration", "decay"].includes(eyeKey)) {
  await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: selfActor, token: token?.document ?? token }), content: "<p><strong>" + EYES[eyeKey].label + ".</strong> Глаз моргает и закрывается влажной плёнкой.</p>" });
}
`
].join("\n");

function addUtilityActivity(itemData, name, offset) {
  const source = clone(itemData);
  const existingIds = new Set(Object.keys(source.system.activities ?? {}));
  source.system.activation = { type: "action", cost: 1, condition: "" };
  CONFIG.DND5E.activityTypes.utility.documentClass.createInitialActivity(source, { offset });
  const activity = activityValues(source.system.activities).find((entry) => !existingIds.has(entry._id)) ?? activityValues(source.system.activities).at(-1);
  activity.name = name;
  activity.img = IMG;
  activity.sort = offset;
  itemData.system.activities[activity._id] = activity;
}

function addSaveActivity(itemData, { name, ability = "wis", range = 60, damageParts = [], offset }) {
  const source = clone(itemData);
  const existingIds = new Set(Object.keys(source.system.activities ?? {}));
  source.system.actionType = "save";
  source.system.activation = { type: "action", cost: 1, condition: "" };
  source.system.range = { value: range, units: "ft" };
  source.system.target = { value: 1, type: "creature", units: "", prompt: true };
  source.system.save = { ability, dc: 18, scaling: "flat" };
  source.system.damage = { parts: damageParts };
  CONFIG.DND5E.activityTypes.save.documentClass.createInitialActivity(source, { offset });
  const activity = activityValues(source.system.activities).find((entry) => !existingIds.has(entry._id)) ?? activityValues(source.system.activities).at(-1);
  activity.name = name;
  activity.img = IMG;
  activity.sort = offset;
  itemData.system.activities[activity._id] = activity;
}

function addAttackActivity(itemData, { name, range = 60, damageParts = [], offset }) {
  const source = clone(itemData);
  const existingIds = new Set(Object.keys(source.system.activities ?? {}));
  source.system.actionType = "rsak";
  source.system.activation = { type: "action", cost: 1, condition: "" };
  source.system.attack = { bonus: "", flat: false };
  source.system.ability = "cha";
  source.system.range = { value: range, long: null, units: "ft" };
  source.system.target = { value: 1, type: "creature", units: "", prompt: true };
  source.system.damage = { parts: damageParts };
  CONFIG.DND5E.activityTypes.attack.documentClass.createInitialActivity(source, { offset });
  const activity = activityValues(source.system.activities).find((entry) => !existingIds.has(entry._id)) ?? activityValues(source.system.activities).at(-1);
  activity.name = name;
  activity.img = IMG;
  activity.sort = offset;
  itemData.system.activities[activity._id] = activity;
}

function buildActivities(itemData) {
  itemData.system.activities = {};
  addUtilityActivity(itemData, "Настроить активные глаза", 0);
  addUtilityActivity(itemData, "Проверка проклятия 30 дней", 1);
  addSaveActivity(itemData, { name: EYES.charm.label, ability: "wis", range: 60, offset: 2 });
  addSaveActivity(itemData, { name: EYES.paralysis.label, ability: "con", range: 60, offset: 3 });
