async function createOrUpdateJournal(folderId, item, dryRun) {
  const existing = game.journal.find((entry) => entry.getFlag("ai-patcher", "bundleId") === BUNDLE_ID || entry.name === JOURNAL_NAME);
  if (dryRun) return { action: existing ? "update" : "create", type: "JournalEntry", name: JOURNAL_NAME };
  const data = {
    name: JOURNAL_NAME,
    folder: folderId,
    flags: { "ai-patcher": { bundleId: BUNDLE_ID, role: "beholder-crown-handout" } },
    pages: [
      {
        name: ITEM_NAME,
        type: "text",
        text: { format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML, content: journalContent(item) }
      }
    ]
  };
  if (existing) return existing.update(data);
  return JournalEntry.create(data);
}

export default async function patch({ dryRun, log, bundle }) {
  IMG = asset(bundle, IMG_PATH);
  if (game.system.id !== "dnd5e") throw new Error("«Корона Десятитысячного Взора v1.1» создана для системы dnd5e.");

  const existing = game.items.find((item) => item.getFlag("ai-patcher", "bundleId") === BUNDLE_ID || item.name === ITEM_NAME);
  if (dryRun) {
    return {
      item: ITEM_NAME,
      action: existing ? "update" : "create",
      activeEyesDefault: DEFAULT_ACTIVE_EYES.map((key) => EYES[key].label),
      activities: ["Настроить активные глаза", ...Object.values(EYES).map((eye) => eye.label)],
      image: IMG
    };
  }

  log(`Создание или обновление предмета: ${ITEM_NAME}`);
  const itemFolder = await getOrCreateFolder(FOLDER_NAME, "Item");
  const journalFolder = await getOrCreateFolder(FOLDER_NAME, "JournalEntry");
  const data = buildItemData(itemFolder.id);

  let item;
  if (existing) {
    item = await existing.update(data);
  } else {
    item = await Item.create(data);
  }
  await item.setFlag("world", "tenThousandfoldGazeActiveEyes", DEFAULT_ACTIVE_EYES);
  await createOrUpdateJournal(journalFolder.id, item, false);

  return {
    item: item.uuid,
    name: item.name,
    activities: activityValues(item.system.activities).map((activity) => activity.name),
    image: item.img
  };
}
